fields.InputDefinition:
{
  "goal": "Use the 'Search everything' box (Ctrl+K) in the top bar to run a global search — type a broad term such as 'Certification'. Verify the global search executes and shows a results panel/list with one or more results from across entities. The search is functional if a results list appears (you do NOT need to find one specific record). Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "The global 'Search everything' box accepted a query and executed it",
    "A search results panel/list with one or more results is displayed",
    "No error messages, blank screens, or crash pages"
  ]
}
